PANTHEON_DELTA_CATEGORIES = {
    "forensics": {"name": "Forensics & Investigation", "agents": FORENSICS_AGENTS, "color": "#4B5563"},
    "espionage": {"name": "Espionage & Intelligence", "agents": ESPIONAGE_AGENTS, "color": "#1F2937"},
    "martial_arts": {"name": "Martial Arts & Combat", "agents": MARTIAL_ARTS_AGENTS, "color": "#DC2626"},
    "theater": {"name": "Theater & Performance", "agents": THEATER_AGENTS, "color": "#7C3AED"},
}

def get_all_pantheon_delta_agents() -> list:
    agents = []
    for cat_id, cat in PANTHEON_DELTA_CATEGORIES.items():
        for agent in cat["agents"]:
            agents.append({"id": agent["id"], "name": agent["name"], "role": agent["role"], "specialty": agent["specialty"], "color": agent["color"], "category": cat_id, "category_name": cat["name"]})
    return agents

def get_pantheon_delta_prompt(agent_id: str, context: str) -> tuple:
    for cat_id, cat in PANTHEON_DELTA_CATEGORIES.items():
        for agent in cat["agents"]:
            if agent["id"] == agent_id:
                return (f"{agent['persona']}\n\nYou are part of the Expert Pantheon (Delta Division).", f"As {agent['name']} ({agent['role']}), apply your expertise to:\n\n{context}")
    return ("You are a domain expert.", f"Analyze: {context}")
